// src/core/quantum_sim.zig
const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;
const Random = std.rand.Random;
const DefaultPrng = std.rand.DefaultPrng;
const c = @cImport({
    @cInclude("complex.h");
    @cInclude("math.h");
    @cInclude("qiskit.h");  // Stub for Qiskit C bindings if available
});

const Tensor = @import("tensor_core.zig").Tensor;

pub const Qubit = enum { |0>, |1> };

pub const QuantumState = struct {
    allocator: Allocator,
    amplitudes: []c_double_complex,
    num_qubits: usize = 0,
    is_normalized: bool = true,

    pub fn init(allocator: Allocator, num_qubits: usize) !QuantumState {
        const size = @as(usize, 1) << @intCast(num_qubits);
        const amplitudes = try allocator.alloc(c_double_complex, size);
        @memset(amplitudes, .{ .re = 1.0, .im = 0.0 });
        amplitudes[0] = .{ .re = 1.0, .im = 0.0 };
        for (1..size) |i| {
            amplitudes[i] = .{ .re = 0.0, .im = 0.0 };
        }
        return QuantumState{
            .allocator = allocator,
            .amplitudes = amplitudes,
            .num_qubits = num_qubits,
        };
    }

    pub fn deinit(self: *QuantumState) void {
        self.allocator.free(self.amplitudes);
    }

    pub fn normalize(self: *QuantumState) void {
        var norm_sq: f64 = 0.0;
        const size = self.amplitudes.len;
        for (0..size) |i| {
            const amp = self.amplitudes[i];
            norm_sq += amp.re * amp.re + amp.im * amp.im;
        }
        const norm = math.sqrt(norm_sq);
        if (norm > 0.0) {
            const inv_norm = 1.0 / norm;
            for (0..size) |i| {
                self.amplitudes[i].re *= inv_norm;
                self.amplitudes[i].im *= inv_norm;
            }
        }
        self.is_normalized = true;
    }

    pub fn apply_hadamard(self: *QuantumState, qubit_idx: usize) void {
        if (qubit_idx >= self.num_qubits) return;
        const size = self.amplitudes.len;
        const stride = @as(usize, 1) << @intCast(qubit_idx);
        var i: usize = 0;
        while (i < size) : (i += 2 * stride) {
            var j: usize = 0;
            while (j < stride) : (j += 1) {
                const idx0 = i + j;
                const idx1 = idx0 + stride;
                const amp0 = self.amplitudes[idx0];
                const amp1 = self.amplitudes[idx1];
                const h_amp0 = .{ .re = (amp0.re + amp1.re) / math.sqrt(2.0), .im = (amp0.im + amp1.im) / math.sqrt(2.0) };
                const h_amp1 = .{ .re = (amp0.re - amp1.re) / math.sqrt(2.0), .im = (amp0.im - amp1.im) / math.sqrt(2.0) };
                self.amplitudes[idx0] = h_amp0;
                self.amplitudes[idx1] = h_amp1;
            }
        }
        self.is_normalized = false;  // Re-normalize if needed
    }

    pub fn apply_cnot(self: *QuantumState, control_idx: usize, target_idx: usize) void {
        if (control_idx >= self.num_qubits or target_idx >= self.num_qubits) return;
        const size = self.amplitudes.len;
        const control_stride = @as(usize, 1) << @intCast(control_idx);
        const target_stride = @as(usize, 1) << @intCast(target_idx);
        var i: usize = 0;
        while (i < size) : (i += 2 * control_stride) {
            var j: usize = 0;
            while (j < control_stride) : (j += 1) {
                const base = i + j;
                const control0_base = base;
                const control1_base = base + control_stride;
                // For control=0 block, copy as is
                var k: usize = 0;
                while (k < target_stride) : (k += 1) {
                    const idx0 = control0_base + k;
                    const idx1 = control0_base + k + target_stride;
                    const temp = self.amplitudes[idx1];
                    self.amplitudes[idx1] = self.amplitudes[idx0];
                    self.amplitudes[idx0] = temp;  // Swap for target flip when control=1
                }
                // For control=1 block, swap target states
                k = 0;
                while (k < target_stride) : (k += 1) {
                    const idx0 = control1_base + k;
                    const idx1 = control1_base + k + target_stride;
                    const temp = self.amplitudes[idx1];
                    self.amplitudes[idx1] = self.amplitudes[idx0];
                    self.amplitudes[idx0] = temp;
                }
            }
        }
        self.is_normalized = false;
    }

    pub fn apply_rx(self: *QuantumState, qubit_idx: usize, angle: f64) void {
        if (qubit_idx >= self.num_qubits) return;
        const cos_half = math.cos(angle / 2.0);
        const sin_half = math.sin(angle / 2.0);
        const size = self.amplitudes.len;
        const stride = @as(usize, 1) << @intCast(qubit_idx);
        var i: usize = 0;
        while (i < size) : (i += 2 * stride) {
            var j: usize = 0;
            while (j < stride) : (j += 1) {
                const idx0 = i + j;
                const idx1 = idx0 + stride;
                const amp0 = self.amplitudes[idx0];
                const amp1 = self.amplitudes[idx1];
                self.amplitudes[idx0] = .{ .re = cos_half * amp0.re - sin_half * amp1.im, .im = cos_half * amp0.im + sin_half * amp1.re };
                self.amplitudes[idx1] = .{ .re = sin_half * amp0.im + cos_half * amp1.re, .im = -sin_half * amp0.re + cos_half * amp1.im };
            }
        }
        self.is_normalized = true;  // Unitary
    }

    pub fn apply_rz(self: *QuantumState, qubit_idx: usize, angle: f64) void {
        if (qubit_idx >= self.num_qubits) return;
        const cos = math.cos(angle / 2.0);
        const sin = math.sin(angle / 2.0);
        const size = self.amplitudes.len;
        const stride = @as(usize, 1) << @intCast(qubit_idx);
        var i: usize = 0;
        while (i < size) : (i += 2 * stride) {
            var j: usize = 0;
            while (j < stride) : (j += 1) {
                const idx0 = i + j;
                const idx1 = idx0 + stride;
                const amp0 = self.amplitudes[idx0];
                const amp1 = self.amplitudes[idx1];
                self.amplitudes[idx0].re *= cos;
                self.amplitudes[idx0].im *= cos;
                self.amplitudes[idx0].im -= sin * amp0.re;
                self.amplitudes[idx1].re *= cos;
                self.amplitudes[idx1].im *= cos;
                self.amplitudes[idx1].im += sin * amp1.re;
            }
        }
        self.is_normalized = true;
    }

    pub fn measure(self: *QuantumState, allocator: Allocator, rng: *DefaultPrng) !usize {
        self.normalize();
        const size = self.amplitudes.len;
        var probs = try allocator.alloc(f64, size);
        defer allocator.free(probs);
        var sum: f64 = 0.0;
        for (0..size) |i| {
            const amp = self.amplitudes[i];
            probs[i] = amp.re * amp.re + amp.im * amp.im;
            sum += probs[i];
        }
        const rand = rng.random().float(f64) * sum;
        var cumulative: f64 = 0.0;
        for (0..size) |i| {
            cumulative += probs[i];
            if (rand <= cumulative) {
                // Collapse state
                const prob = probs[i];
                if (prob > 0.0) {
                    const sqrt_prob = math.sqrt(prob);
                    for (0..size) |j| {
                        if (j == i) {
                            self.amplitudes[j] = .{ .re = 1.0, .im = 0.0 };
                        } else {
                            self.amplitudes[j] = .{ .re = 0.0, .im = 0.0 };
                        }
                    }
                }
                return i;
            }
        }
        return 0;
    }

    pub fn tensor_product(self: *QuantumState, other: *const QuantumState, allocator: Allocator) !QuantumState {
        if (self.num_qubits + other.num_qubits > 64) return error.TooManyQubits;
        const new_size = self.amplitudes.len * other.amplitudes.len;
        const new_amplitudes = try allocator.alloc(c_double_complex, new_size);
        @memset(new_amplitudes, .{ .re = 0.0, .im = 0.0 });
        for (0..self.amplitudes.len) |i| {
            for (0..other.amplitudes.len) |j| {
                const idx = i * other.amplitudes.len + j;
                const re = self.amplitudes[i].re * other.amplitudes[j].re - self.amplitudes[i].im * other.amplitudes[j].im;
                const im = self.amplitudes[i].re * other.amplitudes[j].im + self.amplitudes[i].im * other.amplitudes[j].re;
                new_amplitudes[idx] = .{ .re = re, .im = im };
            }
        }
        return QuantumState{
            .allocator = allocator,
            .amplitudes = new_amplitudes,
            .num_qubits = self.num_qubits + other.num_qubits,
        };
    }

    pub fn fidelity(self: *const QuantumState, other: *const QuantumState) f64 {
        if (self.num_qubits != other.num_qubits) return 0.0;
        var fid: f64 = 0.0;
        const size = self.amplitudes.len;
        for (0..size) |i| {
            const re = self.amplitudes[i].re * other.amplitudes[i].re + self.amplitudes[i].im * other.amplitudes[i].im;
            fid += re * re;
        }
        return fid;
    }

    pub fn to_tensor(self: *const QuantumState, allocator: Allocator) !Tensor {
        const size = self.amplitudes.len * 2;
        const shape = &[_]usize{ @as(usize, 1) << @intCast(self.num_qubits), 2 };
        var tensor = try Tensor.init(allocator, shape, .c64);
        for (0..self.amplitudes.len) |i| {
            const row = i / 2;
            const col = @mod(i, 2);
            if (col == 0) {
                try tensor.set(&.{ row, 0 }, self.amplitudes[i].re);
            } else {
                try tensor.set(&.{ row, 1 }, self.amplitudes[i].im);
            }
        }
        return tensor;
    }

    pub fn from_tensor(tensor: *const Tensor, allocator: Allocator) !QuantumState {
        if (tensor.shape.len != 2 or tensor.shape[1] != 2 or tensor.dtype != .c64) return error.InvalidTensor;
        const num_qubits = try math.log2_int(usize, tensor.shape[0]);
        const size = @as(usize, 1) << @intCast(num_qubits);
        if (size * 2 != tensor.shape[0] * tensor.shape[1]) return error.ShapeMismatch;
        const amplitudes = try allocator.alloc(c_double_complex, size);
        for (0..size) |i| {
            const re = tensor.get(&.{ i, 0 });
            const im = tensor.get(&.{ i, 1 });
            amplitudes[i] = .{ .re = re, .im = im };
        }
        return QuantumState{
            .allocator = allocator,
            .amplitudes = amplitudes,
            .num_qubits = num_qubits,
        };
    }

    test "quantum state init and hadamard" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        var state = try QuantumState.init(allocator, 1);
        defer state.deinit();
        state.apply_hadamard(0);
        state.normalize();
        try testing.expectApproxEqAbs(f64, 0.7071, state.amplitudes[0].re, 1e-4);
        try testing.expectApproxEqAbs(f64, 0.7071, state.amplitudes[1].re, 1e-4);
    }

    test "cnot application" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        var state = try QuantumState.init(allocator, 2);
        defer state.deinit();
        state.amplitudes[2] = .{ .re = 1.0, .im = 0.0 };  // |10>
        state.apply_cnot(0, 1);
        try testing.expectEqual(f64, 1.0, state.amplitudes[2].re);  // Still |10>
        state.amplitudes[3] = .{ .re = 1.0, .im = 0.0 };  // Superposition |11>
        state.apply_cnot(0, 1);
        try testing.expectEqual(f64, 1.0, state.amplitudes[3].re);  // |11> to |11>
    }

    test "rx rotation" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        var state = try QuantumState.init(allocator, 1);
        defer state.deinit();
        state.apply_rx(0, math.pi / 2.0);
        try testing.expectApproxEqAbs(f64, 0.7071, state.amplitudes[0].re, 1e-4);
        try testing.expectApproxEqAbs(f64, 0.7071, state.amplitudes[1].re, 1e-4);
    }

    test "measure collapse" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        var prng = std.rand.DefaultPrng.init(42);
        var state = try QuantumState.init(allocator, 1);
        defer state.deinit();
        state.apply_hadamard(0);
        const outcome = try state.measure(allocator, &prng);
        try testing.expect(outcome < 2);
    }

    pub fn simulate_shots(self: *QuantumState, allocator: Allocator, shots: usize, rng: *DefaultPrng) ![]usize {
        const size = self.amplitudes.len;
        var outcomes = try allocator.alloc(usize, shots);
        for (0..shots) |shot| {
            var temp_state = try self.clone(allocator);
            const outcome = try temp_state.measure(allocator, rng);
            outcomes[shot] = outcome;
            temp_state.deinit();
        }
        return outcomes;
    }

    fn clone(self: *const QuantumState, allocator: Allocator) !QuantumState {
        const size = self.amplitudes.len;
        const new_amplitudes = try allocator.alloc(c_double_complex, size);
        @memcpy(@as([*]u8, @ptrCast(new_amplitudes)), @as([*]const u8, @ptrCast(self.amplitudes)), size * @sizeOf(c_double_complex));
        return QuantumState{
            .allocator = allocator,
            .amplitudes = new_amplitudes,
            .num_qubits = self.num_qubits,
            .is_normalized = self.is_normalized,
        };
    }

    pub fn bell_state(self: *QuantumState, allocator: Allocator) !QuantumState {
        var state = try self.clone(allocator);
        state.apply_hadamard(0);
        state.apply_cnot(0, 1);
        return state;
    }

    pub fn ghz_state(self: *QuantumState, allocator: Allocator, num_qubits: usize) !QuantumState {
        var state = try self.init(allocator, num_qubits);
        state.apply_hadamard(0);
        for (0..num_qubits - 1) |i| {
            state.apply_cnot(i, i + 1);
        }
        return state;
    }

    pub fn swap_gates(self: *QuantumState, q1: usize, q2: usize) void {
        if (q1 == q2) return;
        var temp_state = self.*;  // Copy for swap
        const size = temp_state.amplitudes.len;
        const stride1 = @as(usize, 1) << @intCast(q1);
        const stride2 = @as(usize, 1) << @intCast(q2);
        var mask1: usize = 0;
        var mask2: usize = 0;
        if (q1 > q2) {
            mask1 = stride2 - 1;
            mask2 = stride1 - 1;
        } else {
            mask1 = stride1 - 1;
            mask2 = stride2 - 1;
        }
        for (0..size) |i| {
            const bit1 = (i >> @intCast(q1)) & 1;
            const bit2 = (i >> @intCast(q2)) & 1;
            const new_i = i ^ (bit1 << @intCast(q2)) ^ (bit2 << @intCast(q1));
            const temp = temp_state.amplitudes[i];
            temp_state.amplitudes[i] = temp_state.amplitudes[new_i];
            temp_state.amplitudes[new_i] = temp;
        }
        self.* = temp_state;
    }

    pub fn controlled_rotation(self: *QuantumState, control: usize, target: usize, angle: f64, axis: enum { x, y, z }) void {
        // Implement controlled Rx, Ry, Rz based on axis
        _ = axis;  // Stub
        self.apply_rx(target, angle / 2.0);  // Simplified
    }

    pub fn phase_shift(self: *QuantumState, qubit: usize, phase: f64) void {
        if (qubit >= self.num_qubits) return;
        const stride = @as(usize, 1) << @intCast(qubit);
        var i: usize = stride;
        while (i < self.amplitudes.len) : (i += 2 * stride) {
            var j: usize = 0;
            while (j < stride) : (j += 1) {
                const idx = i + j;
                self.amplitudes[idx].re *= math.cos(phase);
                self.amplitudes[idx].im *= math.sin(phase);
            }
        }
    }

    pub fn density_matrix(self: *const QuantumState, allocator: Allocator) !Tensor {
        const size = self.amplitudes.len;
        const shape = &[_]usize{ size, size };
        var dm = try Tensor.init(allocator, shape, .c64);
        for (0..size) |i| {
            for (0..size) |j| {
                const re = self.amplitudes[i].re * self.amplitudes[j].re + self.amplitudes[i].im * self.amplitudes[j].im;
                const im = self.amplitudes[i].re * self.amplitudes[j].im - self.amplitudes[i].im * self.amplitudes[j].re;
                try dm.set(&.{ i, j }, re + im * 1i);  // Complex
            }
        }
        return dm;
    }

    pub fn partial_trace(self: *const QuantumState, trace_qubits: []usize, allocator: Allocator) !Tensor {
        // Implement partial trace over specified qubits
        _ = trace_qubits;
        return Tensor.init(allocator, &.{1, 1}, .c64);  // Stub
    }

    pub fn entanglement_entropy(self: *const QuantumState, partition: usize, allocator: Allocator) f64 {
        const dm = self.density_matrix(allocator) catch return 0.0;
        defer dm.deinit();
        var entropy: f64 = 0.0;
        const size = dm.shape[0];
        for (0..size) |i| {
            const eig = dm.get(&.{ i, i }).real;  // Simplified eigenvalues
            if (eig > 0.0) {
                entropy -= eig * math.log(eig);
            }
        }
        return entropy;
    }

    // Celestial phase integration
    pub fn apply_celestial_phase(self: *QuantumState, phi_sun: f64, phi_moon: f64) void {
        const combined_phi = phi_sun + phi_moon;
        for (0..self.num_qubits) |q| {
            const q_phase = combined_phi * @as(f64, @floatFromInt(q + 1));
            self.phase_shift(q, q_phase);
        }
    }

    // ZO perturbation via quantum oracle
    pub fn zo_quantum_oracle(self: *QuantumState, perturbation: f64, oracle_func: fn (*QuantumState) void, allocator: Allocator) !f64 {
        var pos_state = try self.clone(allocator);
        pos_state.apply_rx(0, perturbation);
        oracle_func(&pos_state);
        const pos_fid = self.fidelity(&pos_state);
        pos_state.deinit();

        var neg_state = try self.clone(allocator);
        neg_state.apply_rx(0, -perturbation);
        oracle_func(&neg_state);
        const neg_fid = self.fidelity(&neg_state);
        neg_state.deinit();

        return (pos_fid - neg_fid) / (2.0 * perturbation);
    }

    // Astro-Lorenz quantum embedding
    pub fn lorenz_quantum_embed(self: *QuantumState, sigma: f64, rho: f64, beta: f64, dt: f64, steps: usize, allocator: Allocator) !QuantumState {
        var traj = try self.init(allocator, 3 * steps);  // Embed trajectory
        var x: f64 = 0.1; var y: f64 = 1.0; var z: f64 = 1.05;
        for (0..steps) |_|
        {
            const dx = sigma * (y - x);
            const dy = x * (rho - z) - y;
            const dz = x * y - beta * z;
            x += dt * dx; y += dt * dy; z += dt * dz;
            // Encode into qubits
            const phase_x = x * math.pi;
            traj.apply_rz(3 * @intCast(@mulAdd(f64, @as(f64, @floatFromInt(_)), 1.0, 0.0)), phase_x);
            const phase_y = y * math.pi;
            traj.apply_rz(3 * @intCast(@mulAdd(f64, @as(f64, @floatFromInt(_)), 1.0, 1.0)), phase_y);
            const phase_z = z * math.pi;
            traj.apply_rz(3 * @intCast(@mulAdd(f64, @as(f64, @floatFromInt(_)), 1.0, 2.0)), phase_z);
        }
        return traj;
    }

    // TGN quantum message passing simulation
    pub fn quantum_tgn_update(self: *QuantumState, edge_amps: []c_double_complex, node_amps: []c_double_complex, allocator: Allocator) !QuantumState {
        const num_nodes = self.num_qubits / 3;  // Assume 3 qubits per node
        var updated = try self.clone(allocator);
        for (0..num_nodes) |node| {
            var agg_amp: c_double_complex = .{ .re = 0.0, .im = 0.0 };
            for (0..edge_amps.len) |e| {
                agg_amp.re += edge_amps[e].re;
                agg_amp.im += edge_amps[e].im;
            }
            const node_start = node * 3;
            updated.amplitudes[node_start] = cmath_add(updated.amplitudes[node_start], agg_amp);
        }
        return updated;
    }

    fn cmath_add(a: c_double_complex, b: c_double_complex) c_double_complex {
        return .{ .re = a.re + b.re, .im = a.im + b.im };
    }

    fn cmath_mul(a: c_double_complex, b: c_double_complex) c_double_complex {
        return .{ .re = a.re * b.re - a.im * b.im, .im = a.re * b.im + a.im * b.re };
    }

    // Formal verification: unitary preservation
    pub fn assert_unitary(self: *const QuantumState) bool {
        var norm_sq: f64 = 0.0;
        const size = self.amplitudes.len;
        for (0..size) |i| {
            const amp = self.amplitudes[i];
            norm_sq += amp.re * amp.re + amp.im * amp.im;
        }
        return math.approxEqAbs(f64, norm_sq, 1.0, 1e-10, 1e-10);
    }

    // End of quantum_sim.zig
};

