const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;

const Complex = struct {
    re: f64,
    im: f64,
};

pub const Qubit = enum { zero, one };

pub const QuantumState = struct {
    allocator: Allocator,
    amplitudes: []Complex,
    num_qubits: usize = 0,
    is_normalized: bool = true,

    pub fn init(allocator: Allocator, num_qubits: usize) !QuantumState {
        const size = @as(usize, 1) << @intCast(num_qubits);
        const amplitudes = try allocator.alloc(Complex, size);
        std.mem.set(Complex, amplitudes, .{ .re = 0.0, .im = 0.0 });
        amplitudes = .{ .re = 1.0, .im = 0.0 };
        return QuantumState{
            .allocator = allocator,
            .amplitudes = amplitudes,
            .num_qubits = num_qubits,
            .is_normalized = true,
        };
    }

    pub fn deinit(self: *QuantumState) void {
        self.allocator.free(self.amplitudes);
        self.amplitudes = &.{};
        self.num_qubits = 0;
        self.is_normalized = true;
    }

    pub fn normalize(self: *QuantumState) void {
        var norm_sq: f64 = 0.0;
        const size = self.amplitudes.len;
        for (0..size) |i| {
            const amp = self.amplitudes[i];
            norm_sq += amp.re * amp.re + amp.im * amp.im;
        }
        const norm = math.sqrt(norm_sq);
        if (norm > 0.0) {
            const inv_norm = 1.0 / norm;
            for (0..size) |i| {
                self.amplitudes[i].re *= inv_norm;
                self.amplitudes[i].im *= inv_norm;
            }
        }
        self.is_normalized = true;
    }

    pub fn apply_hadamard(self: *QuantumState, qubit_idx: usize) void {
        if (qubit_idx >= self.num_qubits) return;
        const size = self.amplitudes.len;
        const stride = @as(usize, 1) << @intCast(qubit_idx);
        const inv_sqrt2 = 1.0 / math.sqrt(2.0);
        var i: usize = 0;
        while (i < size) : (i += 2 * stride) {
            var j: usize = 0;
            while (j < stride) : (j += 1) {
                const idx0 = i + j;
                const idx1 = idx0 + stride;
                const a0 = self.amplitudes[idx0];
                const a1 = self.amplitudes[idx1];
                self.amplitudes[idx0] = .{
                    .re = (a0.re + a1.re) * inv_sqrt2,
                    .im = (a0.im + a1.im) * inv_sqrt2,
                };
                self.amplitudes[idx1] = .{
                    .re = (a0.re - a1.re) * inv_sqrt2,
                    .im = (a0.im - a1.im) * inv_sqrt2,
                };
            }
        }
        self.is_normalized = false;
    }

    pub fn apply_cnot(self: *QuantumState, control_idx: usize, target_idx: usize) void {
        if (control_idx >= self.num_qubits or target_idx >= self.num_qubits) return;
        if (control_idx == target_idx) return;
        const size = self.amplitudes.len;
        const target_mask = @as(usize, 1) << @intCast(target_idx);
        var i: usize = 0;
        while (i < size) : (i += 1) {
            const control_bit = (i >> @intCast(control_idx)) & 1;
            const target_bit = (i >> @intCast(target_idx)) & 1;
            if (control_bit == 1 and target_bit == 0) {
                const j = i ^ target_mask;
                const tmp = self.amplitudes[i];
                self.amplitudes[i] = self.amplitudes[j];
                self.amplitudes[j] = tmp;
            }
        }
        self.is_normalized = false;
    }

    pub fn apply_rx(self: *QuantumState, qubit_idx: usize, angle: f64) void {
        if (qubit_idx >= self.num_qubits) return;
        const cos_half = math.cos(angle / 2.0);
        const sin_half = math.sin(angle / 2.0);
        const size = self.amplitudes.len;
        const stride = @as(usize, 1) << @intCast(qubit_idx);
        var i: usize = 0;
        while (i < size) : (i += 2 * stride) {
            var j: usize = 0;
            while (j < stride) : (j += 1) {
                const idx0 = i + j;
                const idx1 = idx0 + stride;
                const a0 = self.amplitudes[idx0];
                const a1 = self.amplitudes[idx1];
                const new0 = Complex{
                    .re = cos_half * a0.re + sin_half * a1.im,
                    .im = cos_half * a0.im - sin_half * a1.re,
                };
                const new1 = Complex{
                    .re = sin_half * a0.im + cos_half * a1.re,
                    .im = -sin_half * a0.re + cos_half * a1.im,
                };
                self.amplitudes[idx0] = new0;
                self.amplitudes[idx1] = new1;
            }
        }
        self.is_normalized = true;
    }

    pub fn apply_ry(self: *QuantumState, qubit_idx: usize, angle: f64) void {
        if (qubit_idx >= self.num_qubits) return;
        const cos_half = math.cos(angle / 2.0);
        const sin_half = math.sin(angle / 2.0);
        const size = self.amplitudes.len;
        const stride = @as(usize, 1) << @intCast(qubit_idx);
        var i: usize = 0;
        while (i < size) : (i += 2 * stride) {
            var j: usize = 0;
            while (j < stride) : (j += 1) {
                const idx0 = i + j;
                const idx1 = idx0 + stride;
                const a0 = self.amplitudes[idx0];
                const a1 = self.amplitudes[idx1];
                const new0 = Complex{
                    .re = cos_half * a0.re - sin_half * a1.re,
                    .im = cos_half * a0.im - sin_half * a1.im,
                };
                const new1 = Complex{
                    .re = sin_half * a0.re + cos_half * a1.re,
                    .im = sin_half * a0.im + cos_half * a1.im,
                };
                self.amplitudes[idx0] = new0;
                self.amplitudes[idx1] = new1;
            }
        }
        self.is_normalized = true;
    }

    pub fn apply_rz(self: *QuantumState, qubit_idx: usize, angle: f64) void {
        if (qubit_idx >= self.num_qubits) return;
        const cos_half = math.cos(angle / 2.0);
        const sin_half = math.sin(angle / 2.0);
        const size = self.amplitudes.len;
        const stride = @as(usize, 1) << @intCast(qubit_idx);
        var i: usize = 0;
        while (i < size) : (i += 2 * stride) {
            var j: usize = 0;
            while (j < stride) : (j += 1) {
                const idx0 = i + j;
                const idx1 = idx0 + stride;
                const a0 = self.amplitudes[idx0];
                const a1 = self.amplitudes[idx1];
                self.amplitudes[idx0] = .{
                    .re = a0.re * cos_half + a0.im * sin_half,
                    .im = -a0.re * sin_half + a0.im * cos_half,
                };
                self.amplitudes[idx1] = .{
                    .re = a1.re * cos_half - a1.im * sin_half,
                    .im = a1.re * sin_half + a1.im * cos_half,
                };
            }
        }
        self.is_normalized = true;
    }

    pub fn measure(self: *QuantumState, allocator: Allocator, rng: *std.rand.DefaultPrng) !usize {
        self.normalize();
        const size = self.amplitudes.len;
        var probs = try allocator.alloc(f64, size);
        defer allocator.free(probs);
        var sum: f64 = 0.0;
        for (0..size) |i| {
            const amp = self.amplitudes[i];
            const p = amp.re * amp.re + amp.im * amp.im;
            probs[i] = p;
            sum += p;
        }
        if (sum <= 0.0) return 0;
        const r = rng.random().float(f64) * sum;
        var cumulative: f64 = 0.0;
        for (0..size) |i| {
            cumulative += probs[i];
            if (r <= cumulative) {
                for (0..size) |j| {
                    self.amplitudes[j] = if (j == i) .{ .re = 1.0, .im = 0.0 } else .{ .re = 0.0, .im = 0.0 };
                }
                self.is_normalized = true;
                return i;
            }
        }
        return size - 1;
    }

    pub fn tensor_product(self: *QuantumState, other: *const QuantumState, allocator: Allocator) !QuantumState {
        if (self.num_qubits + other.num_qubits > 62) return error.TooManyQubits;
        const new_size = self.amplitudes.len * other.amplitudes.len;
        const new_amplitudes = try allocator.alloc(Complex, new_size);
        var idx: usize = 0;
        for (0..self.amplitudes.len) |i| {
            for (0..other.amplitudes.len) |j| {
                const a = self.amplitudes[i];
                const b = other.amplitudes[j];
                new_amplitudes[idx] = .{
                    .re = a.re * b.re - a.im * b.im,
                    .im = a.re * b.im + a.im * b.re,
                };
                idx += 1;
            }
        }
        return QuantumState{
            .allocator = allocator,
            .amplitudes = new_amplitudes,
            .num_qubits = self.num_qubits + other.num_qubits,
            .is_normalized = self.is_normalized and other.is_normalized,
        };
    }

    pub fn fidelity(self: *const QuantumState, other: *const QuantumState) f64 {
        if (self.num_qubits != other.num_qubits) return 0.0;
        const size = self.amplitudes.len;
        var re_sum: f64 = 0.0;
        var im_sum: f64 = 0.0;
        for (0..size) |i| {
            const a = self.amplitudes[i];
            const b = other.amplitudes[i];
            const re = a.re * b.re + a.im * b.im;
            const im = -a.im * b.re + a.re * b.im;
            re_sum += re;
            im_sum += im;
        }
        return re_sum * re_sum + im_sum * im_sum;
    }

    pub fn simulate_shots(self: *QuantumState, allocator: Allocator, shots: usize, rng: *std.rand.DefaultPrng) ![]usize {
        var outcomes = try allocator.alloc(usize, shots);
        for (0..shots) |shot| {
            var temp_state = try self.clone(allocator);
            const outcome = try temp_state.measure(allocator, rng);
            outcomes[shot] = outcome;
            temp_state.deinit();
        }
        return outcomes;
    }

    fn clone(self: *const QuantumState, allocator: Allocator) !QuantumState {
        const size = self.amplitudes.len;
        const new_amplitudes = try allocator.alloc(Complex, size);
        std.mem.copyForwards(Complex, new_amplitudes, self.amplitudes);
        return QuantumState{
            .allocator = allocator,
            .amplitudes = new_amplitudes,
            .num_qubits = self.num_qubits,
            .is_normalized = self.is_normalized,
        };
    }

    pub fn bell_state(self: *QuantumState, allocator: Allocator) !QuantumState {
        if (self.num_qubits < 2) return error.InsufficientQubits;
        var state = try self.clone(allocator);
        state.apply_hadamard(0);
        state.apply_cnot(0, 1);
        return state;
    }

    pub fn ghz_state(_: *QuantumState, allocator: Allocator, num_qubits: usize) !QuantumState {
        if (num_qubits < 2) return error.InsufficientQubits;
        var state = try QuantumState.init(allocator, num_qubits);
        state.apply_hadamard(0);
        var i: usize = 0;
        while (i + 1 < num_qubits) : (i += 1) {
            state.apply_cnot(i, i + 1);
        }
        return state;
    }

    pub fn swap_gates(self: *QuantumState, q1: usize, q2: usize) void {
        if (q1 >= self.num_qubits or q2 >= self.num_qubits) return;
        if (q1 == q2) return;
        const mask = (@as(usize, 1) << @intCast(q1)) | (@as(usize, 1) << @intCast(q2));
        const size = self.amplitudes.len;
        var i: usize = 0;
        while (i < size) : (i += 1) {
            const b1 = (i >> @intCast(q1)) & 1;
            const b2 = (i >> @intCast(q2)) & 1;
            if (b1 == 1 and b2 == 0) {
                const j = i ^ mask;
                const tmp = self.amplitudes[i];
                self.amplitudes[i] = self.amplitudes[j];
                self.amplitudes[j] = tmp;
            }
        }
        self.is_normalized = false;
    }

    pub const Axis = enum { x, y, z };

    pub fn controlled_rotation(self: *QuantumState, control: usize, target: usize, angle: f64, axis: Axis) void {
        if (control >= self.num_qubits or target >= self.num_qubits) return;
        if (control == target) return;
        const size = self.amplitudes.len;
        const target_mask = @as(usize, 1) << @intCast(target);
        switch (axis) {
            .x => {
                const cos_half = math.cos(angle / 2.0);
                const sin_half = math.sin(angle / 2.0);
                var i: usize = 0;
                while (i < size) : (i += 1) {
                    const cbit = (i >> @intCast(control)) & 1;
                    const tbit = (i >> @intCast(target)) & 1;
                    if (cbit == 1 and tbit == 0) {
                        const j = i ^ target_mask;
                        const a0 = self.amplitudes[i];
                        const a1 = self.amplitudes[j];
                        const new0 = Complex{
                            .re = cos_half * a0.re + sin_half * a1.im,
                            .im = cos_half * a0.im - sin_half * a1.re,
                        };
                        const new1 = Complex{
                            .re = sin_half * a0.im + cos_half * a1.re,
                            .im = -sin_half * a0.re + cos_half * a1.im,
                        };
                        self.amplitudes[i] = new0;
                        self.amplitudes[j] = new1;
                    }
                }
            },
            .y => {
                const cos_half = math.cos(angle / 2.0);
                const sin_half = math.sin(angle / 2.0);
                var i: usize = 0;
                while (i < size) : (i += 1) {
                    const cbit = (i >> @intCast(control)) & 1;
                    const tbit = (i >> @intCast(target)) & 1;
                    if (cbit == 1 and tbit == 0) {
                        const j = i ^ target_mask;
                        const a0 = self.amplitudes[i];
                        const a1 = self.amplitudes[j];
                        const new0 = Complex{
                            .re = cos_half * a0.re - sin_half * a1.re,
                            .im = cos_half * a0.im - sin_half * a1.im,
                        };
                        const new1 = Complex{
                            .re = sin_half * a0.re + cos_half * a1.re,
                            .im = sin_half * a0.im + cos_half * a1.im,
                        };
                        self.amplitudes[i] = new0;
                        self.amplitudes[j] = new1;
                    }
                }
            },
            .z => {
                const cos_half = math.cos(angle / 2.0);
                const sin_half = math.sin(angle / 2.0);
                var i: usize = 0;
                while (i < size) : (i += 1) {
                    const cbit = (i >> @intCast(control)) & 1;
                    const tbit = (i >> @intCast(target)) & 1;
                    if (cbit == 1 and tbit == 0) {
                        const j = i ^ target_mask;
                        const a0 = self.amplitudes[i];
                        const a1 = self.amplitudes[j];
                        self.amplitudes[i] = .{
                            .re = a0.re * cos_half + a0.im * sin_half,
                            .im = -a0.re * sin_half + a0.im * cos_half,
                        };
                        self.amplitudes[j] = .{
                            .re = a1.re * cos_half - a1.im * sin_half,
                            .im = a1.re * sin_half + a1.im * cos_half,
                        };
                    }
                }
            },
        }
        self.is_normalized = true;
    }

    pub fn phase_shift(self: *QuantumState, qubit: usize, phase: f64) void {
        if (qubit >= self.num_qubits) return;
        const size = self.amplitudes.len;
        const stride = @as(usize, 1) << @intCast(qubit);
        const cos_p = math.cos(phase);
        const sin_p = math.sin(phase);
        var i: usize = stride;
        while (i < size) : (i += 2 * stride) {
            var j: usize = 0;
            while (j < stride) : (j += 1) {
                const idx = i + j;
                const a = self.amplitudes[idx];
                self.amplitudes[idx] = .{
                    .re = a.re * cos_p - a.im * sin_p,
                    .im = a.re * sin_p + a.im * cos_p,
                };
            }
        }
        self.is_normalized = true;
    }

    pub fn apply_celestial_phase(self: *QuantumState, phi_sun: f64, phi_moon: f64) void {
        const combined = phi_sun + phi_moon;
        for (0..self.num_qubits) |q| {
            const q_phase = combined * @as(f64, @floatFromInt(q + 1));
            self.phase_shift(q, q_phase);
        }
    }

    pub fn zo_quantum_oracle(self: *QuantumState, perturbation: f64, oracle_func: fn (*QuantumState) void, allocator: Allocator) !f64 {
        var pos_state = try self.clone(allocator);
        pos_state.apply_rx(0, perturbation);
        oracle_func(&pos_state);
        const pos_fid = self.fidelity(&pos_state);
        pos_state.deinit();

        var neg_state = try self.clone(allocator);
        neg_state.apply_rx(0, -perturbation);
        oracle_func(&neg_state);
        const neg_fid = self.fidelity(&neg_state);
        neg_state.deinit();

        return (pos_fid - neg_fid) / (2.0 * perturbation);
    }

    pub fn quantum_tgn_update(self: *QuantumState, edge_amps: []Complex, node_amps: []Complex, allocator: Allocator) !QuantumState {
        _ = node_amps;
        const num_nodes = if (self.num_qubits >= 3) self.num_qubits / 3 else 0;
        var updated = try self.clone(allocator);
        for (0..num_nodes) |node| {
            var agg: Complex = .{ .re = 0.0, .im = 0.0 };
            for (0..edge_amps.len) |e| {
                agg.re += edge_amps[e].re;
                agg.im += edge_amps[e].im;
            }
            const node_start = node * 3;
            if (node_start < updated.amplitudes.len) {
                updated.amplitudes[node_start] = .{
                    .re = updated.amplitudes[node_start].re + agg.re,
                    .im = updated.amplitudes[node_start].im + agg.im,
                };
            }
        }
        updated.is_normalized = false;
        return updated;
    }

    pub fn assert_unitary(self: *const QuantumState) bool {
        var norm_sq: f64 = 0.0;
        const size = self.amplitudes.len;
        for (0..size) |i| {
            const a = self.amplitudes[i];
            norm_sq += a.re * a.re + a.im * a.im;
        }
        return std.math.approxEqAbs(f64, norm_sq, 1.0, 1e-10);
    }

    test "quantum state init and hadamard" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        var state = try QuantumState.init(allocator, 1);
        defer state.deinit();
        state.apply_hadamard(0);
        state.normalize();
        try testing.expectApproxEqAbs(0.7071, state.amplitudes.re, 1e-4);
        try testing.expectApproxEqAbs(0.7071, state.amplitudes.re, 1e-4);
        try testing.expectApproxEqAbs(0.0, state.amplitudes.im, 1e-9);
        try testing.expectApproxEqAbs(0.0, state.amplitudes.im, 1e-9);
    }

    test "cnot application" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        var state = try QuantumState.init(allocator, 2);
        defer state.deinit();
        std.mem.set(Complex, state.amplitudes, .{ .re = 0.0, .im = 0.0 });
        state.amplitudes = .{ .re = 1.0, .im = 0.0 };
        state.apply_cnot(0, 1);
        try testing.expectEqual(@as(f64, 1.0), state.amplitudes.re);
        try testing.expectApproxEqAbs(0.0, state.amplitudes.im, 1e-12);
        std.mem.set(Complex, state.amplitudes, .{ .re = 0.0, .im = 0.0 });
        state.amplitudes = .{ .re = 1.0, .im = 0.0 };
        state.apply_cnot(0, 1);
        try testing.expectEqual(@as(f64, 1.0), state.amplitudes.re);
        try testing.expectApproxEqAbs(0.0, state.amplitudes.re, 1e-12);
    }

    test "rx rotation" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        var state = try QuantumState.init(allocator, 1);
        defer state.deinit();
        state.apply_rx(0, math.pi / 2.0);
        try testing.expectApproxEqAbs(0.7071, state.amplitudes.re, 1e-4);
        try testing.expectApproxEqAbs(0.0, state.amplitudes.im, 1e-9);
        try testing.expectApproxEqAbs(0.0, state.amplitudes.re, 1e-9);
        try testing.expectApproxEqAbs(-0.7071, state.amplitudes.im, 1e-4);
    }

    test "measure collapse" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        var prng = std.rand.DefaultPrng.init(42);
        var state = try QuantumState.init(allocator, 1);
        defer state.deinit();
        state.apply_hadamard(0);
        const outcome = try state.measure(allocator, &prng);
        try testing.expect(outcome < 2);
    }
